// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }

    // fuzzed params: caller key (as uint256) to derive an address, and amount to send
    function testFuzz_property(uint256 callerKey, uint256 amount) public {
        // Keep domain wide but sensible: callerKey corresponds to the deployer/owner in setUp()? setUp used msg.sender as owner,
        // which is this test contract. We want the caller to be the owner so the require(msg.sender==owner) passes and execution proceeds to the external call.
        // Derive owner address from this test (the test contract itself) by using address(this). We'll ensure vm.prank uses address(this).
        // amount must fit into balance we give to c and be nonzero to force an actual transfer attempt; keep it within a large bound.
        amount = bound(amount, 1, 1 ether);

        // Deploy a recipient that WILL revert when receiving Ether to distinguish transfer (reverts) vs send (returns false)
        RevertingRecipient bad = new RevertingRecipient();

        // Fund the contract c so it has balance to attempt transfer/send
        vm.deal(address(c), amount);

        // Ensure the call is made as the owner: in setUp(), owner = msg.sender where c was deployed (this test contract),
        // so we prank as address(this)
        bool ok;
        vm.prank(address(this));
        // Call sendTo and catch whether it reverted (reference should revert because transfer forwards 2300 gas and revert in recipient will bubble)
        try c.sendTo(address(bad), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule (single assertion): for all admissible inputs (owner caller and any amount within bounds, and a recipient that reverts on receive),
        // the reference implementation using transfer always causes the call to revert, so ok must be false. The mutant that uses send and ignores return
        // may make ok == true for some inputs (the fuzzer will find such an amount), so we assert ok == false here.
        assertTrue(!ok);
    }
}

// Adversarial recipient that always reverts on receiving Ether to expose the difference between transfer (which bubbles) and send (which returns false)
contract RevertingRecipient {
    // Revert on any plain Ether receipt
    receive() external payable {
        revert("nope");
    }
}
